// Literal port of the team's Casa3DSDK (module interaction/target). Generated by codemod and reviewed; see MIGRATION.md.
import type { Kernel, Shared } from '../kernel-types.js';

export function installInteractionTarget(K: Kernel, shared: Shared): void {
  const { doorText, toggleDoor, visibleChain, wallBlocks } = K;
  const ivTarget = (...a: any[]): any => K.ivTarget(...a);
  // interaction target of whoever is at o = {x, y, z, yaw, pitch, floor} (eye, in house coordinates): the best among doors (by distance and angle) and items (anchor, reach, angle or aim ray).
  // opts.hit(meshes) receives the visible meshes of the moving pieces and returns the first intersection (THREE) or nothing: the app casts its own camera ray (aim at the screen centre).
  function targetOf(o, opt) {
    if (!o) return null; opt = opt || {};
    const ex = o.x, ey = o.y, ez = o.z, floor = o.floor, cp = Math.cos(o.pitch || 0), vx = Math.sin(o.yaw) * cp, vy = Math.sin(o.pitch || 0), vz = Math.cos(o.yaw) * cp;
    let best = null; const tries = (score, text, action, target) => { if (!best || score < best.score) best = { score, text, action, target }; };
    for (const fo of shared.ctx.leaves) {
      if (fo.floor !== floor) continue; const d = Math.hypot(fo.cx - ex, fo.cz - ez); if (d > 1.7) continue;
      const angle = Math.acos(Math.max(-1, Math.min(1, ((fo.cx - ex) * vx + (fo.cz - ez) * vz) / (d || 1) / Math.max(0.2, Math.hypot(vx, vz)))));
      if (angle > 1.35 && d > 0.9) continue;
      tries(angle * 1.6 + d * 0.5 + (angle < 0.25 ? 0 : 0.6), doorText(fo), () => toggleDoor(fo), fo);
    }
    const vis = shared.inter.pieces.flatMap(p => p.meshes).filter(visibleChain), hit = vis.length && opt.strike ? opt.strike(vis) : null;
    const kitA = shared.ctx.iv ? ivTarget(shared.ctx.iv, o, opt && opt.interactives) : null; // kit object: if it is between the eye and the piece hit by the ray (mailbox in front of the gate), the piece behind does not count
    const nearKit = kitA && hit && Math.hypot(kitA.target.pos[0] - ex, kitA.target.pos[1] - ey, kitA.target.pos[2] - ez) < hit.distance + 0.1;
    const pieceHit = hit && !nearKit && hit.object.userData.piece;
    for (const it of shared.inter.items) {
      if (it.floor !== floor && !(it.floor === -1 && floor === 0)) continue;
      const [ax, ay, az] = it.anchor, dx = ax - ex, dy = ay - ey, dz = az - ez, d = Math.hypot(dx, dy, dz), dh = Math.hypot(dx, dz); if (dh > it.range + 0.4) continue;
      const angle = Math.acos(Math.max(-1, Math.min(1, (dx * vx + dy * vy + dz * vz) / (d || 1))));
      const byRay = pieceHit && it.pieces.includes(pieceHit) && hit.distance <= it.range + 0.5;
      if (!byRay && !(dh <= it.range && angle <= it.angle)) continue;
      if (!it.noWall && wallBlocks(ex, ez, ax, az, it.floor < 0 ? 0 : it.floor)) continue;
      tries((byRay ? 0 : angle * 2) + d * 0.3 - (byRay ? 1.5 : 0), it.text(), it.action, it);
    }
    if (kitA) tries(kitA.score - (nearKit ? 0.5 : 0), kitA.text, kitA.action, kitA.target);
    return best;
  }
  Object.assign(K, { targetOf });
}
